export const GOOGLE_PLAY_DEVELOPER_URL = "https://play.google.com/store/apps/developer?id=MK+DIGITAL+SYSTEMS";
export const PORTFOLIO_URL = "https://mustafaoner.net";

export function getProduct(id: string) {
  return products.find((product) => product.id === id);
}

export function getProductTopic(productId: string, slug: string) {
  return getProduct(productId)?.topics.find((entry) => entry.slug === slug);
}

export function productUrl(product: Product | ProductId) {
  return `/tr/${typeof product === "string" ? product : product.id}`;
}

export function topicUrl(product: Product | ProductId, entry: SeoTopic | string) {
  return `${productUrl(product)}/${typeof entry === "string" ? entry : entry.slug}`;
}

